package dev.wildcraft.test;

import com.google.gson.GsonBuilder;
import java.nio.file.Files;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.inventory.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.phys.*;

/** Actual natural wood and native crafting inputs, with one explicitly provided initial nearby tree location. */
public final class EarlyAcquisitionClientTest implements FabricClientGameTest {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private static int count(Player p,Item item){int n=0;for(int i=0;i<36;i++)if(p.getInventory().getItem(i).is(item))n+=p.getInventory().getItem(i).getCount();return n;}
    private static void aim(ClientGameTestContext c,Vec3 target){c.runOnClient(v->{var d=target.subtract(v.player.getEyePosition());v.player.setYRot((float)Math.toDegrees(Math.atan2(-d.x,d.z)));v.player.setXRot((float)-Math.toDegrees(Math.atan2(d.y,Math.sqrt(d.horizontalDistanceSqr()))));});c.waitTicks(2);}
    private static int slot(ClientGameTestContext c,Item item){return c.computeOnClient(v->{for(var s:v.player.containerMenu.slots)if(s.container==v.player.getInventory()&&s.getItem().is(item))return s.index;throw new AssertionError("Native inventory lacks "+item);});}
    private static void click(ClientGameTestContext c,int slot,int button,ContainerInput action){c.runOnClient(v->v.gameMode.handleContainerInput(v.player.containerMenu.containerId,slot,button,action,v.player));c.waitTicks(2);}
    private static void grid(ClientGameTestContext c,Item item,int...cells){int origin=slot(c,item);click(c,origin,0,ContainerInput.PICKUP);for(int cell:cells){int actual=c.computeOnClient(v->((AbstractCraftingMenu)v.player.containerMenu).getInputGridSlots().get(cell).index);click(c,actual,1,ContainerInput.PICKUP);}click(c,origin,0,ContainerInput.PICKUP);}
    private static void take(ClientGameTestContext c,Item result){c.waitFor(v->((AbstractCraftingMenu)v.player.containerMenu).getResultSlot().getItem().is(result));int at=c.computeOnClient(v->((AbstractCraftingMenu)v.player.containerMenu).getResultSlot().index);click(c,at,0,ContainerInput.QUICK_MOVE);c.waitFor(v->v.player.containerMenu.getCarried().isEmpty());}
    private static Map<String,Object> result(Player p,BlockPos table){return Map.of("woodenPickaxes",count(p,Items.WOODEN_PICKAXE),"woodenAxes",count(p,Items.WOODEN_AXE),"axeDamage",p.getMainHandItem().is(Items.WOODEN_AXE)?p.getMainHandItem().getDamageValue():-1,"planks",count(p,Items.OAK_PLANKS),"sticks",count(p,Items.STICK),"logs",count(p,Items.OAK_LOG),"carriedTables",count(p,Items.CRAFTING_TABLE),"tableInWorld",p.level().getBlockState(table).is(Blocks.CRAFTING_TABLE),"inventorySlots",p.inventoryMenu.slots.size());}
    @Override public void runTest(ClientGameTestContext c){
        boolean axe=Boolean.getBoolean("wildcraft.test.earlyAcquisitionAxe");TestWorldSave save;BlockPos root,table;Map<String,Object> beforeSave;var audit=new LinkedHashMap<String,Object>();
        try(TestSingleplayerContext w=c.worldBuilder().setUseConsistentSettings(false).adjustSettings(s->s.setSeed("1")).create()){
            w.getConnection().waitForChunksRender();
            root=w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(!p.isCreative()&&!p.isSpectator(),"Native new world survival");check(p.getInventory().isEmpty(),"Actually empty new inventory, no fixture items");check(s.overworld().getSeed()==1,"Deterministic normal world seed");check(!s.overworld().getChunkSource().getGenerator().getClass().getSimpleName().contains("Flat"),"Normal generated terrain, not superflat");var center=p.blockPosition();int oakColumns=0,bases=0;var rejected=new ArrayList<String>();
                for(int radius=0;radius<=48;radius++)for(int dx=-radius;dx<=radius;dx++)for(int dz=-radius;dz<=radius;dz++){
                    if(Math.max(Math.abs(dx),Math.abs(dz))!=radius)continue;int x=center.getX()+dx,z=center.getZ()+dz;if(!s.overworld().hasChunk(x>>4,z>>4))continue;int top=s.overworld().getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,x,z);
                    for(int y=Math.max(s.overworld().getMinY(),top-12);y<top;y++){var b=new BlockPos(x,y,z);if(s.overworld().getBlockState(b).is(Blocks.OAK_LOG))oakColumns++;if(!s.overworld().getBlockState(b).is(Blocks.OAK_LOG)||!s.overworld().getBlockState(b.above()).is(Blocks.OAK_LOG)||!s.overworld().getBlockState(b.above(2)).is(Blocks.OAK_LOG)||!s.overworld().getBlockState(b.below()).is(Blocks.DIRT))continue;
                        bases++;boolean safe=true;for(int qx=0;qx<=2;qx++)for(int qz=-2;qz<=0;qz++){var f=b.offset(qx,0,qz);if(!s.overworld().getBlockState(f.below()).isCollisionShapeFullBlock(s.overworld(),f.below())||!s.overworld().getFluidState(f).isEmpty()||(!f.equals(b)&&!s.overworld().getBlockState(f).getCollisionShape(s.overworld(),f).isEmpty())||(!f.equals(b)&&!s.overworld().getBlockState(f.above()).getCollisionShape(s.overworld(),f.above()).isEmpty()))safe=false;}
                        if(!s.overworld().getBlockState(b.east(2)).isAir())safe=false;if(!safe){if(rejected.size()<3)rejected.add(b.toString()+" ground="+s.overworld().getBlockState(b.offset(2,-1,0))+" stand="+s.overworld().getBlockState(b.offset(0,0,-2))+" table="+s.overworld().getBlockState(b.offset(2,0,0)));continue;}p.teleportTo(s.overworld(),x+.5,y,z-1.3,Set.of(),0,0,true);return b;
                    }
                }throw new AssertionError("No safe natural oak found within48 already generated blocks: logs="+oakColumns+" bases="+bases+" rejected="+rejected);});
            table=root.east(2);audit.put("seed",1);audit.put("root",List.of(root.getX(),root.getY(),root.getZ()));audit.put("providedInitialTreeTeleport",true);audit.put("materialsGranted",false);audit.put("normalWorld",true);c.waitFor(v->v.player.distanceToSqr(root.getX()+.5,root.getY(),root.getZ()-1.3)<.2&&v.player.onGround());c.takeScreenshot("c7-natural-empty-start");
            for(int i=0;i<3;i++){var log=root.above(i);aim(c,Vec3.atBottomCenterOf(log).add(0,.02,0));try{c.waitFor(v->v.hitResult instanceof BlockHitResult h&&h.getBlockPos().equals(log));}catch(AssertionError e){c.takeScreenshot("c7-natural-aim-failure-"+i);throw new AssertionError("Natural log "+i+" target="+log+" observed="+c.computeOnClient(v->(v.hitResult instanceof BlockHitResult h ? h.getBlockPos().toString() : String.valueOf(v.hitResult))+" player="+v.player.position()+" pitch="+v.player.getXRot()+" yaw="+v.player.getYRot()),e);}System.out.println("C7 ACQUISITION native mining log="+i+" pos="+log);try{c.getInput().holdKey(v->v.keyAttack);w.getServer().waitFor(s->s.overworld().getBlockState(log).isAir(),150);}finally{c.getInput().releaseKey(v->v.keyAttack);}c.waitTicks(3);}
            aim(c,new Vec3(root.getX()+.5,c.computeOnClient(v->v.player.getEyeY()),root.getZ()+.5));try{c.getInput().holdKey(v->v.keyUp);c.waitFor(v->v.player.distanceToSqr(root.getX()+.5,root.getY(),root.getZ()+.5)<.4,80);}finally{c.getInput().releaseKey(v->v.keyUp);}c.waitFor(v->count(v.player,Items.OAK_LOG)==3);w.getServer().runOnServer(s->check(count(s.getPlayerList().getPlayers().getFirst(),Items.OAK_LOG)==3,"Three actual broken natural logs picked up"));c.takeScreenshot("c7-natural-three-logs");
            c.getInput().pressKey(v->v.keyInventory);c.waitForScreen(InventoryScreen.class);check(c.computeOnClient(v->v.player.inventoryMenu.slots.size()==47),"Existing46 native inventory slots plus one glider slot");
            int origin=slot(c,Items.OAK_LOG);click(c,origin,0,ContainerInput.PICKUP);int first=c.computeOnClient(v->v.player.inventoryMenu.getInputGridSlots().getFirst().index);click(c,first,0,ContainerInput.PICKUP);take(c,Items.OAK_PLANKS);c.waitFor(v->count(v.player,Items.OAK_PLANKS)==12);c.takeScreenshot("c7-natural-native-planks");
            grid(c,Items.OAK_PLANKS,0,1,2,3);take(c,Items.CRAFTING_TABLE);c.waitFor(v->count(v.player,Items.CRAFTING_TABLE)==1&&count(v.player,Items.OAK_PLANKS)==8);
            grid(c,Items.OAK_PLANKS,0,2);take(c,Items.STICK);c.waitFor(v->count(v.player,Items.STICK)==4&&count(v.player,Items.OAK_PLANKS)==6);
            click(c,slot(c,Items.CRAFTING_TABLE),8,ContainerInput.SWAP);c.getInput().pressKey(v->v.keyInventory);c.waitForScreen(null);c.getInput().pressKey(v->v.keyHotbarSlots[8]);c.waitFor(v->v.player.getMainHandItem().is(Items.CRAFTING_TABLE));aim(c,Vec3.atBottomCenterOf(table).add(0,-.01,0));c.waitFor(v->v.hitResult instanceof BlockHitResult h&&h.getBlockPos().equals(table.below()));
            try{c.getInput().holdKey(v->v.keyUse);w.getServer().waitFor(s->s.overworld().getBlockState(table).is(Blocks.CRAFTING_TABLE));}finally{c.getInput().releaseKey(v->v.keyUse);}c.waitTicks(3);c.takeScreenshot("c7-natural-native-table-placed");
            aim(c,Vec3.atCenterOf(table));c.getInput().pressKey(v->v.keyUse);c.waitForScreen(CraftingScreen.class);grid(c,Items.OAK_PLANKS,0,1,2);grid(c,Items.STICK,4,7);take(c,Items.WOODEN_PICKAXE);c.waitFor(v->count(v.player,Items.WOODEN_PICKAXE)==1&&count(v.player,Items.OAK_PLANKS)==3&&count(v.player,Items.STICK)==2);c.takeScreenshot("c7-natural-native-wooden-pickaxe");
            if(axe){grid(c,Items.OAK_PLANKS,0,1,3);grid(c,Items.STICK,4,7);take(c,Items.WOODEN_AXE);c.waitFor(v->count(v.player,Items.WOODEN_AXE)==1&&count(v.player,Items.OAK_PLANKS)==0&&count(v.player,Items.STICK)==0);click(c,slot(c,Items.WOODEN_AXE),8,ContainerInput.SWAP);c.takeScreenshot("c7-natural-native-wooden-axe");}
            c.runOnClient(v->v.player.closeContainer());c.waitForScreen(null);
            if(axe){
                c.getInput().pressKey(v->v.keyHotbarSlots[8]);c.waitFor(v->v.player.getMainHandItem().is(Items.WOODEN_AXE));var log=root.above(3);w.getServer().runOnServer(s->check(s.overworld().getBlockState(log).is(Blocks.OAK_LOG),"Fourth natural trunk log remains"));aim(c,Vec3.atBottomCenterOf(log).add(0,.02,0));c.waitFor(v->v.hitResult instanceof BlockHitResult h&&h.getBlockPos().equals(log));
                try{c.getInput().holdKey(v->v.keyAttack);c.waitTicks(2);check(c.computeOnClient(v->!dev.wildcraft.client.combat.MeleeControls.suppressNative()&&dev.wildcraft.combat.MeleeActions.view(v.player).phase()==dev.wildcraft.network.MeleeView.IDLE),"Held original axe mining is not claimed as combat charge");w.getServer().waitFor(s->s.overworld().getBlockState(log).isAir(),120);}finally{c.getInput().releaseKey(v->v.keyAttack);}
                c.waitFor(v->count(v.player,Items.OAK_LOG)==1&&v.player.getMainHandItem().getDamageValue()==1);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getMainHandItem().is(Items.WOODEN_AXE)&&p.getMainHandItem().getDamageValue()==1&&dev.wildcraft.combat.MeleeActions.view(p).phase()==dev.wildcraft.network.MeleeView.IDLE,"Exactly one native block wear, no axe melee action");});audit.put("actualAxeMining",true);audit.put("nativeAxeDamage",1);c.takeScreenshot("c7-natural-native-axe-log-no-combat");
            }
            beforeSave=w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(count(p,Items.WOODEN_PICKAXE)==1&&count(p,Items.OAK_PLANKS)==(axe?0:3)&&count(p,Items.STICK)==(axe?0:2)&&count(p,Items.OAK_LOG)==(axe?1:0)&&count(p,Items.WOODEN_AXE)==(axe?1:0)&&count(p,Items.CRAFTING_TABLE)==0,"Native material accounting3logs->12planks->table/pick/sticks");check(p.inventoryMenu.getCarried().isEmpty(),"No hidden cursor stack");return result(p,table);});save=w.getWorldSave();
        }finally{c.getInput().releaseKey(v->v.keyAttack);c.getInput().releaseKey(v->v.keyUse);c.getInput().releaseKey(v->v.keyUp);}
        try(TestSingleplayerContext w=save.open()){
            w.getConnection().waitForChunksRender();var after=w.getServer().computeOnServer(s->result(s.getPlayerList().getPlayers().getFirst(),table));check(beforeSave.equals(after),"Real world save/reopen keeps acquired items and original table");check(Boolean.TRUE.equals(after.get("tableInWorld")),"Native placed table remains");audit.put("axeVariant",axe);audit.put("beforeSave",beforeSave);audit.put("afterReopen",after);audit.put("complete",true);audit.put("manualSurvivalVerified",false);c.takeScreenshot("c7-natural-reopened-materials");c.runOnClient(v->{try{Files.writeString(v.gameDirectory.toPath().resolve("c7-early-acquisition.json"),new GsonBuilder().setPrettyPrinting().create().toJson(audit)+"\n");}catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}});
        }
        System.out.println("WILDCRAFT C7 NORMAL ACQUISITION native3logs/12planks/table/woodpick plusvariant material accounting and disk reopen passed; one provided initial tree location, not manual survival");
    }
}
